import React, { useState } from "react";
import axios from "axios";

const AddFlower = () => {
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    price: "",
    category: "",
  });

  const [selectedFile, setSelectedFile] = useState(null);
  const [message, setMessage] = useState("");

  // handle text input
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  // handle file input
  const handleFileChange = (e) => {
    setSelectedFile(e.target.files[0]);
  };

  // handle form submit
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!selectedFile) {
      setMessage("Please select an image before submitting.");
      return;
    }

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("name", formData.name);
      formDataToSend.append("description", formData.description);
      formDataToSend.append("price", formData.price);
      formDataToSend.append("category", formData.category);
      formDataToSend.append("image", selectedFile); // file goes here

      const res = await axios.post(
        "https://flower-delivery-website-af2b.onrender.com/api/flowers",
        formDataToSend,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );

      console.log("Saved flower:", res.data);
      setMessage("Flower added successfully!");
      setFormData({ name: "", description: "", price: "", category: "" });
      setSelectedFile(null);
    } catch (err) {
      console.error("Error adding flower:", err);
      setMessage("Failed to add flower. Try again.");
    }
  };

  return (
    <div>
      <h2>Add New Flower</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="name"
          placeholder="Flower Name"
          value={formData.name}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="description"
          placeholder="Description"
          value={formData.description}
          onChange={handleChange}
          required
        />
        <input
          type="number"
          name="price"
          placeholder="Price"
          value={formData.price}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="category"
          placeholder="Category"
          value={formData.category}
          onChange={handleChange}
          required
        />

        <input type="file" accept="image/*" onChange={handleFileChange} required />

        <button type="submit">Add Flower</button>
      </form>

      {message && <p>{message}</p>}
    </div>
  );
};

export default AddFlower;
